"use client";
import React, { JSX, useState } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '../context/AuthContext';
import ErrorMessage from '../components/shared/ErrorMessage';
import { Eye, EyeOff } from 'lucide-react';
import Link from 'next/link';

export default function LoginPage(): JSX.Element {
  const router = useRouter();
  const { login } = useAuth();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [emailWarning, setEmailWarning] = useState<string | null>(null);

  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  // Email validation
  const validateEmail = (email: string) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (email && !emailRegex.test(email)) {
      setEmailWarning('Please enter a valid email address');
    } else {
      setEmailWarning(null);
    }
  };

  const handleEmailChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setEmail(value);
    validateEmail(value);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccessMessage(null);

    // Final validation before submit
    if (!email || !password) {
      setError('Please fill in all fields');
      return;
    }

    if (emailWarning) {
      setError('Please fix the errors before submitting');
      return;
    }

    setLoading(true);
    try {
      const result = await login(email, password);
      if (result.success) {
        setSuccessMessage('Login successful! Redirecting...');
        // Delay redirect to show success message
        setTimeout(() => {
          router.push('/');
        }, 1000);
      } else {
        setError(result.error || 'Invalid credentials');
      }
    } catch (err: any) {
      setError(err?.message || 'Invalid credentials');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex justify-center items-center min-h-screen bg-gray-50">
      <form
        onSubmit={handleSubmit}
        className="flex flex-col gap-3 bg-white p-8 w-full max-w-md rounded-2xl shadow-md font-[system-ui]"
      >
        {/* Email Field */}
        <div className="flex flex-col">
          <label className="text-gray-800 font-semibold mb-1" htmlFor="email">
            Email
          </label>
          <div className={`flex items-center border rounded-lg h-12 px-3 transition ${emailWarning ? 'border-amber-400 focus-within:border-amber-500' : 'border-gray-200 focus-within:border-blue-500'
            }`}>
            <input
              id="email"
              name="email"
              type="email"
              autoComplete="off"
              value={email}
              onChange={handleEmailChange}
              onBlur={() => validateEmail(email)}
              placeholder="Enter your email"
              className="w-full border-none outline-none bg-transparent text-gray-700 placeholder-gray-400"
            />
          </div>
          {emailWarning && (
            <div className="mt-2">
              <ErrorMessage variant="warning" message={emailWarning} />
            </div>
          )}
        </div>

        {/* Password Field */}
        <div className="flex flex-col mt-3">
          <label className="text-gray-800 font-semibold mb-1" htmlFor="password">
            Password
          </label>
          <div className="flex items-center border border-gray-200 rounded-lg h-12 px-3 focus-within:border-blue-500 transition">
            <input
              id="password"
              name="password"
              type={showPassword ? 'text' : 'password'}
              autoComplete="off"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter your password"
              className="w-full border-none outline-none bg-transparent text-gray-700 placeholder-gray-400"
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="ml-2 text-gray-500 hover:text-gray-700 focus:outline-none"
            >
              {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
            </button>
          </div>
        </div>

        {/* Remember me + Forgot Password */}
        <div className="flex justify-between items-center mt-2 text-sm">
          <label className="flex items-center space-x-2">
            <input type="checkbox" className="accent-blue-500" />
            <span className="text-gray-700">Remember me</span>
          </label>
          <span className="text-blue-600 cursor-pointer hover:underline">Forgot password?</span>
        </div>

        {successMessage && <ErrorMessage variant="success" message={successMessage} />}
        {error && <ErrorMessage error={error} />}

        {/* Submit */}
        <button
          disabled={loading}
          type="submit"
          className="w-full mt-4 bg-gray-900 text-white py-3 rounded-lg font-medium hover:bg-gray-800 transition disabled:opacity-60"
        >
          {loading ? 'Signing in...' : 'Sign In'}
        </button>

        {/* Sign Up */}
        <p className="text-center text-gray-700 text-sm mt-2">
          Don’t have an account?{' '}
          <Link href='/signUp' className="text-blue-600 font-medium cursor-pointer hover:underline">Sign Up</Link>
        </p>

        <p className="text-center text-gray-500 text-sm my-2">Or With</p>

        {/* OAuth Buttons */}
        <button
          type="button"
          className="flex items-center justify-center gap-2 border border-gray-200 rounded-lg py-3 hover:border-blue-500 transition"
        >
          <img
            src="https://unpkg.com/simple-icons@v10/icons/google.svg"
            alt="Google"
            className="w-5 h-5"
          />
          Continue with Google
        </button>

        <button
          type="button"
          className="flex items-center justify-center gap-2 border border-gray-200 rounded-lg py-3 hover:border-blue-500 transition"
        >
          <img
            src="https://unpkg.com/simple-icons@v10/icons/apple.svg"
            alt="Apple"
            className="w-5 h-5"
          />
          Continue with Apple
        </button>
      </form>
    </div>
  );
}
